<template><AppShell><StatePanel v-if="loading||error" :loading="loading" :error="error" @retry="load"/><template v-else-if="graph"><view class="detail-crumb"><button class="text-button" @tap="go('person',{id})">← {{personName}}档案</button><text>人物与时代 · 关系图谱</text></view><view class="page-heading atlas-heading"><text class="eyebrow">循关系读人 / RELATION ATLAS</text><text class="page-title">从一个人，走近一段时代</text><text class="muted">点节点读说明，点连线看依据。可沿已收录的机构与人物联系，逐层展开。</text></view><view class="atlas-path"><view><text class="atlas-root">{{personName}}</text><text v-if="trail.length"> › {{graph.nodes[0]?.name}}</text><text v-else class="small"> · 直接关联</text></view><view class="atlas-path-actions"><button v-if="trail.length" @tap="previous">返回上一层</button><button v-if="trail.length" @tap="reset">回到{{personName}}</button></view></view><view v-if="expandError" class="atlas-feedback"><text>{{expandError}}</text><button @tap="expand(selected)">重试展开</button></view><view class="atlas-layout"><view class="atlas-map"><RelationGraph :graph="graph" :selected-id="selected?.id" @node="selectNode" @edge="selectEdge" @source="sourceId=$event"/></view><view class="atlas-inspector" :class="{'inspector-open':drawer}" v-if="selected"><view class="inspector-heading"><view><text class="eyebrow">节点阅读 / {{kindLabel(selected.kind)}}</text><text class="inspector-name">{{selected.name}}</text></view><button class="inspector-close" @tap="drawer=false" aria-label="关闭节点说明">×</button></view><text v-if="selected.period" class="atlas-period">{{selected.period}}</text><text v-if="selected.description!==selectedEvidence[0]?.excerpt" class="inspector-copy">{{selected.description||'可从下方关系记载与来源继续阅读。'}}</text><view class="inspector-stats"><text>{{selected.related_count||0}} 条已收录联系</text><text>{{selected.source_count||0}} 份来源</text></view><view v-if="selected.person_id||selected.event_id||(selected.id!==graph.anchor_id&&(selected.related_count||0)>1)" class="inspector-actions"><button v-if="selected.id!==graph.anchor_id&&(selected.related_count||0)>1" class="primary" :disabled="expanding" @tap="expand(selected)">{{expanding?'正在展开…':'展开此节点关系'}}</button><button v-if="selected.person_id" class="outline" @tap="go('person',{id:selected.person_id})">阅读人物档案</button><button v-if="selected.event_id" class="outline" @tap="go('event',{id:selected.event_id})">阅读事件片段</button></view><text v-if="expandError" class="inspector-feedback">{{expandError}}</text><text class="inspector-section">与当前中心的记载</text><view v-if="!selectedEvidence.length" class="inspector-empty">可选择图中的另一个节点，查看它与当前中心的联系。</view><view v-for="e in selectedEvidence" :key="e.id" class="inspector-evidence"><text class="inspector-relation">{{nameFor(e.from_id)}} · {{e.type}} · {{nameFor(e.to_id)}}</text><text>{{e.excerpt}}</text><button v-if="e.source_id" class="text-button" @tap="sourceId=e.source_id">查看引用与出处 ↗</button></view></view></view><view v-if="drawer" class="inspector-backdrop" @touchmove.stop.prevent @tap="drawer=false"/></template><SourceSheet :source-id="sourceId" @close="sourceId=''"/></AppShell></template>
<script setup>
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue';import {onLoad,onShow,onShareAppMessage} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import RelationGraph from '../../components/RelationGraph.vue';import StatePanel from '../../components/StatePanel.vue';import SourceSheet from '../../components/SourceSheet.vue';import {api} from '../../lib/api.js';import {go} from '../../lib/navigation.js';
const graph=ref(null),personName=ref('人物'),loading=ref(true),error=ref(''),sourceId=ref(''),selected=ref(null),drawer=ref(false),expanding=ref(false),expandError=ref(''),trail=ref([]);let id='P009',initial=null,sequence=0,restoreDrawer=false;
watch(sourceId,(next,prev)=>{if(next){restoreDrawer=drawer.value;drawer.value=false}else if(prev&&restoreDrawer){drawer.value=true;restoreDrawer=false}});
const kindLabel=k=>({person:'人物',collective:'人物群体',group:'组织',school:'学校',publication:'刊物',event:'事件',place:'地点',artifact:'作品',record:'史料',entity:'关联对象'}[k]||'关联对象');
const nameFor=id=>graph.value?.nodes.find(n=>n.id===id)?.name||'关联对象';
const selectedEvidence=computed(()=>{const seen=new Set();return (graph.value?.edges||[]).filter(e=>{if(e.from_id!==selected.value?.id&&e.to_id!==selected.value?.id)return false;const key=e.fact_id+'|'+e.source_id;if(seen.has(key))return false;seen.add(key);return true})});
function show(g){graph.value=g;selected.value=g.nodes[0]||null;drawer.value=false;sourceId.value='';expandError.value=''}
async function load(){const token=++sequence;loading.value=true;error.value='';expanding.value=false;try{const [g,p]=await Promise.all([api('people/'+id+'/graph'),api('people/'+id)]);if(token!==sequence)return;personName.value=p.name;initial=g;trail.value=[];show(g)}catch(e){if(token===sequence)error.value=e.message}finally{if(token===sequence)loading.value=false}}
function selectNode(n){selected.value=n;drawer.value=true;expandError.value=''}
function selectEdge(e){const center=graph.value.anchor_id||graph.value.nodes[0]?.id;const node=graph.value.nodes.find(n=>n.id===(e.from_id===center?e.to_id:e.from_id));if(node)selectNode(node)}
async function expand(n){if(!n||expanding.value||n.id===graph.value.anchor_id)return;const token=++sequence;expanding.value=true;expandError.value='';try{const g=await api('people/'+id+'/graph',{focus:n.id});if(token!==sequence)return;trail.value.push(graph.value);show(g)}catch(e){if(token===sequence)expandError.value=e.message}finally{if(token===sequence)expanding.value=false}}
function previous(){if(expanding.value)return;const g=trail.value.pop();if(g)show(g)}function reset(){sequence++;expanding.value=false;trail.value=[];if(initial)show(initial)}
onLoad(q=>{id=q.id||'P009';load()});onShareAppMessage(()=>({title:personName.value+' · 关系图谱',path:'/pages/graph/index?id='+id}));
// #ifdef H5
function syncRoute(){const [route,query='']=location.hash.slice(1).split('?');if(route!=='/pages/graph/index')return;const next=new URLSearchParams(query).get('id')||'P009';if(next!==id){id=next;graph.value=null;drawer.value=false;load()}}function key(e){if(e.key==='Escape'){drawer.value=false;sourceId.value=''}}onShow(syncRoute);onMounted(()=>{window.addEventListener('hashchange',syncRoute);window.addEventListener('keydown',key)});onBeforeUnmount(()=>{sequence++;window.removeEventListener('hashchange',syncRoute);window.removeEventListener('keydown',key)});
// #endif
</script>
<style scoped>
.atlas-heading{margin-bottom:22px}.atlas-path{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:17px;padding:12px 16px;border:1px solid #e2d5bd;background:#f4ecdd;border-radius:10px;color:#8b7554;font-size:13px}.atlas-root{font-family:STSong,SimSun,serif;color:#354d43;font-size:18px}.atlas-path-actions{display:flex;gap:8px}.atlas-path-actions button{margin:0;min-height:34px;line-height:1.6;padding:6px 12px;border:1px solid #d6c5a7;background:#fffaf0;color:#982b28;font-size:12px;border-radius:7px}.atlas-layout{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:20px;align-items:start}.atlas-map{min-width:0}.atlas-inspector{position:sticky;top:18px;padding:23px 20px;border:1px solid #dcc7a5;background:#fffaf1;border-radius:14px;max-height:calc(100vh - 40px);overflow:auto;box-sizing:border-box}.inspector-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}.inspector-heading .eyebrow{font-size:10px;letter-spacing:1px}.inspector-name{display:block;font:25px/1.5 STSong,SimSun,serif;color:#354d43;margin:9px 0 15px}.inspector-close{display:none}.atlas-period{display:block;font-size:12px;color:#a0875f;margin:0 0 12px}.inspector-copy{display:block;font-size:13px;color:#78694f;line-height:1.9}.inspector-stats{display:flex;flex-wrap:wrap;gap:12px;font-size:11px;color:#927b57;margin:18px 0;border-top:1px solid #e4d7c0;border-bottom:1px solid #e4d7c0;padding:12px 0}.inspector-actions{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:22px}.inspector-actions button{margin:0;padding:8px 12px;min-height:38px;font-size:12px;line-height:1.6;display:flex;align-items:center;justify-content:center;border-radius:7px}.inspector-section{font-size:14px;color:#354d43;display:block;margin:5px 0 12px}.inspector-evidence{border-left:2px solid #bd9a67;padding:0 0 0 12px;margin-bottom:20px}.inspector-evidence>text{display:block;font-size:12px;line-height:1.85;color:#75664f}.inspector-evidence .inspector-relation{font-size:12px;color:#982b28;margin-bottom:7px}.inspector-evidence .inspector-boundary{font-size:10px;color:#a18c6d;margin-top:8px}.inspector-evidence button{font-size:11px;padding:6px 0;line-height:1.6;text-align:left;margin:7px 0 0;min-height:32px}.inspector-empty,.inspector-footnote{display:block;font-size:11px;line-height:1.85;color:#9b8768}.inspector-footnote{border-top:1px solid #e4d7c0;padding-top:15px}.atlas-boundary{font-size:12px;line-height:1.9;color:#8f7c60;margin-top:20px}.inspector-backdrop{display:none}.atlas-feedback{display:flex;align-items:center;justify-content:space-between;font-size:12px;padding:12px;margin:10px 0;background:#f3e7d5;color:#982b28}.atlas-feedback button{font-size:12px;padding:6px 10px;margin:0}
@media(max-width:1000px){.atlas-layout{grid-template-columns:1fr}.atlas-inspector{display:none}.atlas-inspector.inspector-open{display:block;position:fixed;left:12px;right:12px;bottom:calc(12px + env(safe-area-inset-bottom));top:auto;max-height:74vh;z-index:2100;padding:22px;border-radius:18px;box-shadow:0 -15px 60px #283b3333}.inspector-backdrop{display:block;position:fixed;inset:0;z-index:2050;background:#23372b66}.inspector-close{display:flex;align-items:center;justify-content:center;margin:0;background:#f2e8d7;color:#982b28;border:0;border-radius:50%;width:34px;height:34px;font-size:23px;line-height:1;flex-shrink:0}.atlas-path{flex-wrap:wrap}.atlas-path-actions{flex-wrap:wrap}.atlas-root{font-size:16px}}
</style>

<style scoped>
.atlas-heading{padding:18px 22px!important;margin-bottom:16px;border-left-width:2px}.atlas-heading .page-title{font-size:30px;line-height:1.45;margin:8px 0}.atlas-heading .eyebrow{font-size:10px}.atlas-heading .muted{font-size:12px}.atlas-path{min-height:48px;padding:10px 15px}.atlas-path .small{display:inline;font-size:11px}.inspector-feedback{display:block;padding:10px;color:#982b28;font-size:12px;line-height:1.8;background:#f6e8d7;border-radius:7px;margin-bottom:14px}.inspector-section{margin-top:0}.inspector-stats{margin-bottom:16px}
@media(max-width:650px){.atlas-heading{padding:15px 18px!important}.atlas-heading .page-title{font-size:25px}.atlas-heading .muted{font-size:11px}.atlas-path{margin-bottom:12px}.atlas-inspector.inspector-open{padding:20px}.inspector-name{font-size:24px;margin-bottom:10px}.inspector-stats{margin-top:8px}}
</style>
